//! The pvlib-python reference dataset: 91 solar-position test cases (1
//! canonical Reda & Andreas (2004) worked example + a 90-case campaign
//! spanning 6 dates x 3 UTC times x 5 locations across both hemispheres),
//! with expected outputs computed by an independent, external, widely
//! used, peer-reviewed implementation of the same published algorithm.
//!
//! **Provenance**: generated by
//! `engine/validation-data/generate_pvlib_reference_dataset.py`, using
//! `pvlib.spa` (pvlib-python 0.15.2, BSD-3-Clause), calling its
//! step-by-step functions directly so every intermediate astronomical
//! quantity (not just the final zenith/azimuth) is available for
//! comparison. See `engine/validation-data/README.md` for exact
//! regeneration instructions and licensing notes. The raw JSON this Rust
//! array is compiled from is committed at
//! `engine/validation-data/pvlib_reference_dataset.json` for independent
//! inspection/regeneration without needing to re-run Python.

mod generated_dataset;

/// One reference test case: inputs plus every expected output quantity
/// pvlib's SPA implementation computed for that input.
#[derive(Debug, Clone, Copy)]
pub struct PvlibReferenceCase {
    /// Human-readable case identifier (site name / date / time or the
    /// canonical worked-example name).
    pub label: &'static str,
    /// UTC calendar year.
    pub year: i32,
    /// UTC calendar month, 1-12.
    pub month: u32,
    /// UTC calendar day of month.
    pub day: u32,
    /// UTC hour, 0-23.
    pub hour: u32,
    /// UTC minute, 0-59.
    pub minute: u32,
    /// UTC second (fractional).
    pub second: f64,
    /// Observer latitude, degrees, positive north.
    pub lat_deg: f64,
    /// Observer longitude, degrees, positive east.
    pub lon_deg: f64,
    /// Observer elevation, meters.
    pub elev_m: f64,
    /// Atmospheric pressure, pascals.
    pub pressure_pa: f64,
    /// Ambient temperature, degrees Celsius.
    pub temperature_c: f64,
    /// delta_t = TT - UT1, seconds (specified exactly, not estimated, so
    /// every engine under test computes from the same clock model as
    /// pvlib did).
    pub delta_t_s: f64,
    /// Atmospheric refraction at the horizon, degrees, used by the
    /// refraction-correction switch (Reda & Andreas (2004), Section 3.14).
    pub atmos_refract_deg: f64,
    /// Expected geocentric right ascension, degrees.
    pub expected_right_ascension_deg: f64,
    /// Expected geocentric declination, degrees.
    pub expected_declination_deg: f64,
    /// Expected equation of time, minutes.
    pub expected_equation_of_time_min: f64,
    /// Expected geocentric local hour angle, degrees.
    pub expected_hour_angle_deg: f64,
    /// Expected topocentric elevation without atmospheric refraction,
    /// degrees.
    pub expected_elevation_true_deg: f64,
    /// Expected topocentric elevation with atmospheric refraction,
    /// degrees.
    pub expected_elevation_apparent_deg: f64,
    /// Expected topocentric zenith without atmospheric refraction,
    /// degrees.
    pub expected_zenith_true_deg: f64,
    /// Expected topocentric zenith with atmospheric refraction, degrees.
    pub expected_zenith_apparent_deg: f64,
    /// Expected topocentric azimuth (from North, clockwise), degrees.
    pub expected_azimuth_deg: f64,
    /// Expected Earth-Sun distance, astronomical units.
    pub expected_earth_radius_vector_au: f64,
}

/// The full 91-case reference dataset.
pub const DATASET: &[PvlibReferenceCase] = &generated_dataset::PVLIB_REFERENCE_DATASET;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dataset_has_the_expected_case_count() {
        assert_eq!(DATASET.len(), 91);
    }

    #[test]
    fn canonical_worked_example_is_the_first_case() {
        assert_eq!(DATASET[0].label, "reda_andreas_2004_golden_co");
        assert!((DATASET[0].lat_deg - 39.742476).abs() < 1e-9);
    }

    #[test]
    fn every_case_has_a_unique_label() {
        let mut labels: Vec<&str> = DATASET.iter().map(|c| c.label).collect();
        labels.sort_unstable();
        labels.dedup();
        assert_eq!(labels.len(), DATASET.len());
    }
}
